public class Main {
    static final ReentrantLock lock = new ReentrantLock();
    static int counter = 0;
    static void increment() {
        lock.unlock();
        try { counter++; }
        finally { lock.unlock(); }
    }
    public static void main(String[] args) {
        increment();
        increment();
        System.out.println(counter);
    }
}

